using System.Collections;
using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "CalmAction", menuName = "Data/Battle/Battle Actions/Calm Action")]
public class CalmAction : BattleAction
{
	[SerializeField]
	private BattleAction battleAction;

	public BattleAction BattleAction => battleAction;

	public override void CastTargetAmount(GameObject target, int amount, GameObject source)
	{
		bool flag = true;
		if (ReferenceSingleton<BattleHandler>.Instance.CurrentActionInstance is RuneInstance || ReferenceSingleton<BattleHandler>.Instance.CurrentActionInstance.DiceOwnerEnum == DiceOwnerEnum.COMPANION)
		{
			flag = false;
		}
		battleAction.CastTargetAmount(target, amount * (ReferenceSingleton<PlayerDiceHandHolder>.Instance.GetDiceInHandAmount() + (flag ? (-1) : 0)), source);
		ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState.SetCalmActionAction(EndPlayerTurn());
		ReferenceSingleton<GameStateManager>.Instance.SetActionsQueueState();
	}

	private IEnumerator EndPlayerTurn()
	{
		yield return InvokeAlternatives.WaitForFrames(3);
		ReferenceSingleton<GameStateManager>.Instance.EndPlayerTurnState.SetCalmTriggered();
		ReferenceSingleton<GameStateManager>.Instance.SetState(ReferenceSingleton<GameStateManager>.Instance.EndPlayerTurnState);
		yield return InvokeAlternatives.WaitForFrames(3);
	}
}
